#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAdmin: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = Admin

    public static func lift(_ handle: UInt64) throws -> Admin {
        return Admin(unsafeFromHandle: handle)
    }

    public static func lower(_ value: Admin) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Admin {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: Admin, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeAdmin_lift(_ handle: UInt64) throws -> Admin {
    return try FfiConverterTypeAdmin.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeAdmin_lower(_ value: Admin) -> UInt64 {
    return FfiConverterTypeAdmin.lower(value)
}






