#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeForeignAuthenticator: FfiConverter {
    fileprivate static let handleMap = UniffiHandleMap<ForeignAuthenticator>()

    typealias FfiType = UInt64
    typealias SwiftType = ForeignAuthenticator

    public static func lift(_ handle: UInt64) throws -> ForeignAuthenticator {
        if ((handle & 1) == 0) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return ForeignAuthenticatorImpl(unsafeFromHandle: handle)
        } else {
            // Swift-generated handle, get the object from the handle map
            return try handleMap.remove(handle: handle)
        }
    }

    public static func lower(_ value: ForeignAuthenticator) -> UInt64 {
         if let rustImpl = value as? ForeignAuthenticatorImpl {
             // Rust-implemented object.  Clone the handle and return it
            return rustImpl.uniffiCloneHandle()
         } else {
            // Swift object, generate a new vtable handle and return that.
            return handleMap.insert(obj: value)
         }
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ForeignAuthenticator {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: ForeignAuthenticator, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeForeignAuthenticator_lift(_ handle: UInt64) throws -> ForeignAuthenticator {
    return try FfiConverterTypeForeignAuthenticator.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeForeignAuthenticator_lower(_ value: ForeignAuthenticator) -> UInt64 {
    return FfiConverterTypeForeignAuthenticator.lower(value)
