/**
 * Seeds (spec §6).
 */
public protocol VaultProtocol: AnyObject, Sendable {
    
    func changePassphrase(seed: String, old: SecretBytes, new: SecretBytes) async throws 
    
    func confirmBackup(seed: String) async throws 
    
    func deriveChild(req: DeriveChild) async throws  -> NewSeed
    
    func deriveFromKey(req: DeriveFromKey) async throws  -> NewSeed
    
    func deriveFromSignature(req: DeriveFromSignature) async throws  -> NewSeed
    
    func disablePrfUnlock(seed: String) async throws 
    
    func enablePasskeyUnlock(seed: String, vaultPassphrase: SecretBytes) async throws 
    
    func enablePlatformUnlock(seed: String, vaultPassphrase: SecretBytes, policy: KeyPolicy) async throws 
    
    func generate(req: Generate) async throws  -> NewSeed
    
    func importKey(req: ImportKey) async throws  -> ImportedKey
    
    func importWords(req: ImportWords) async throws  -> SeedInfo
    
    /**
     * Root (c)'s typed data for the account `account_hex` and set `set` (spec §6.6).
     */
    func keyDerivationTypedData(accountHex: String, set: UInt32) throws  -> String
    
    func keystoreRollback() async throws  -> Bool
    
    /**
     * Locks `seed`: the ids of the hidden sets abandoned with it. A failed call is its error (`Internal`), never an empty
     * answer: the seed is then not known locked.
     */
    func lock(seed: String) async throws  -> [String]
    
    /**
     * Locks every seed (a failed call is its error, as `lock`).
     */
    func lockAll() async throws  -> [String]
    
    /**
     * The memory protection of an unlocked seed's arena.
     */
    func memoryProtection(seed: String) throws  -> MemoryProtection
    
    func openHidden(seed: String, unlock: Unlock, bip39Passphrase: SecretBytes) async throws  -> SessionSet
    
    func remove(req: Remove) async throws 
    
    func rename(seed: String, label: String) async throws 
    
    func seed(seed: String) async throws  -> SeedInfo
    
    func seeds() async throws  -> [SeedInfo]
    
    /**
     * A 65-byte signature from its compact form (a secret in, a secret out).
     */
    func signatureFromCompact(sig: SecretBytes) throws  -> SecretBytes
    
    func unlock(seed: String, unlock: Unlock) async throws 
    
    /**
     * Whether a word (a secret) is on the BIP-39 list.
     */
    func wordInList(word: SecretBytes)  -> Bool
    
}
