#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeWallet: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = Wallet

    public static func lift(_ handle: UInt64) throws -> Wallet {
        return Wallet(unsafeFromHandle: handle)
    }

    public static func lower(_ value: Wallet) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Wallet {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: Wallet, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeWallet_lift(_ handle: UInt64) throws -> Wallet {
    return try FfiConverterTypeWallet.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeWallet_lower(_ value: Wallet) -> UInt64 {
    return FfiConverterTypeWallet.lower(value)
}




/**
 * `accept_membership` (CTR-UA-37): slot `slot` of the `msig` `ua` accepts on `chain`, sent by `payer`.
 */
public struct AcceptMembership: Equatable, Hashable {
    public var chain: String
    public var ua: String
    public var slot: MsigSlot
    public var payer: KeyRef

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(chain: String, ua: String, slot: MsigSlot, payer: KeyRef) {
        self.chain = chain
        self.ua = ua
        self.slot = slot
        self.payer = payer
    }

    

    
}

#if compiler(>=6)
extension AcceptMembership: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAcceptMembership: FfiConverterRustBuffer {
    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AcceptMembership {
        return
            try AcceptMembership(
                chain: FfiConverterString.read(from: &buf), 
                ua: FfiConverterString.read(from: &buf), 
                slot: FfiConverterTypeMsigSlot.read(from: &buf), 
                payer: FfiConverterTypeKeyRef.read(from: &buf)
        )
    }

    public static func write(_ value: AcceptMembership, into buf: inout [UInt8]) {
        FfiConverterString.write(value.chain, into: &buf)
        FfiConverterString.write(value.ua, into: &buf)
        FfiConverterTypeMsigSlot.write(value.slot, into: &buf)
        FfiConverterTypeKeyRef.write(value.payer, into: &buf)
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeAcceptMembership_lift(_ buf: RustBuffer) throws -> AcceptMembership {
    return try FfiConverterTypeAcceptMembership.lift(buf)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeAcceptMembership_lower(_ value: AcceptMembership) -> RustBuffer {
    return FfiConverterTypeAcceptMembership.lower(value)
}


/**
 * One account row as the app shows it.
 */
public struct AccountInfo: Equatable, Hashable {
    public var id: String
    /**
     * The seed the row belongs to (R2).
     */
    public var seed: String
    public var name: String
    /**
     * `ua`, `native`, `key` or `watch`.
     */
    public var shape: String
    public var kind: UInt16?
    public var account: UInt32?
    public var index: UInt32?
    public var network: String?
    /**
     * A UA row's or a key row's UA, a native row's address, a watch row's id.
     */
    public var idText: String
    /**
     * The seed is unlocked and its index MAC verified at unlock (spec §6.2); a locked seed's rows are unverified.
     */
    public var verified: Bool
    /**
     * An EVM row whose code is an EIP-7702 designator (`0xef0100…`), from [`Account::marks`]; the SDK builds no type-4
     * transaction, so it cannot offer to clear it (CLI-SDK-31).
     */
    public var delegated: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(id: String, 
        /**
         * The seed the row belongs to (R2).
         */seed: String, name: String, 
        /**
         * `ua`, `native`, `key` or `watch`.
         */shape: String, kind: UInt16?, account: UInt32?, index: UInt32?, network: String?, 
