/**
 * A liquidity order (`LiquidityOrder`, CTR-DEX-30; dex-liquidity spec §4.2), signed in its DEX's domain.
 */
public struct LiquidityOrder: Equatable, Hashable {
    public var signer: KeyRef
    public var chain: String
    /**
     * a DEX of the profile's list with its liquidity mark
     */
    public var dex: String
    public var inputs: [LiquidityToken]
    public var outputs: [LiquidityToken]
    public var positionManager: String?
    public var positionReader: String?
    public var positionIn: String
    /**
     * `0x` + 64 hex; `None`: no position received
     */
    public var positionPool: String?
    public var tickLower: Int32
    public var tickUpper: Int32
    public var minLiquidity: String
    /**
     * a 32-byte id; `None`: the signer
     */
    public var recipient: String?
    public var fee: String
    public var relayer: String
    public var flags: UInt8
    public var batch: String
    /**
     * the order's nonce (the planner's; no lane is read)
     */
    public var nonce: String
    public var validUntil: UInt64
    /**
     * tokens the plan counts beside its inputs and outputs (at most eight)
     */
    public var extraTokens: [String]
    /**
     * a partial withdraw or fee collect (it must receive the position back)
     */
    public var partial: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(signer: KeyRef, chain: String, 
        /**
         * a DEX of the profile's list with its liquidity mark
         */dex: String, inputs: [LiquidityToken], outputs: [LiquidityToken], positionManager: String?, positionReader: String?, positionIn: String, 
        /**
         * `0x` + 64 hex; `None`: no position received
         */positionPool: String?, tickLower: Int32, tickUpper: Int32, minLiquidity: String, 
        /**
         * a 32-byte id; `None`: the signer
         */recipient: String?, fee: String, relayer: String, flags: UInt8, batch: String, 
        /**
         * the order's nonce (the planner's; no lane is read)
         */nonce: String, validUntil: UInt64, 
        /**
         * tokens the plan counts beside its inputs and outputs (at most eight)
         */extraTokens: [String], 
        /**
         * a partial withdraw or fee collect (it must receive the position back)
         */partial: Bool) {
        self.signer = signer
        self.chain = chain
        self.dex = dex
        self.inputs = inputs
        self.outputs = outputs
        self.positionManager = positionManager
        self.positionReader = positionReader
        self.positionIn = positionIn
        self.positionPool = positionPool
        self.tickLower = tickLower
