// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * An account row, by shape (spec §6.1), each with its fields in the written order.
 */

public enum AccountRow: Equatable, Hashable {
    
    case ua(id: String, name: String, kind: UInt64, account: UInt64, index: UInt64, ua: String
    )
    case native(id: String, name: String, network: String, index: UInt64, coinType: UInt64?, change: UInt64?, path: String?, ss58Prefix: UInt64?, address: String
    )
    case key(id: String, name: String, kind: UInt64, keyData: String, credentialId: String?, handle: String?, ua: String
    )
    case watch(id: String, name: String, watch: String
    )





}

#if compiler(>=6)
extension AccountRow: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAccountRow: FfiConverterRustBuffer {
    typealias SwiftType = AccountRow

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AccountRow {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .ua(id: try FfiConverterString.read(from: &buf), name: try FfiConverterString.read(from: &buf), kind: try FfiConverterUInt64.read(from: &buf), account: try FfiConverterUInt64.read(from: &buf), index: try FfiConverterUInt64.read(from: &buf), ua: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .native(id: try FfiConverterString.read(from: &buf), name: try FfiConverterString.read(from: &buf), network: try FfiConverterString.read(from: &buf), index: try FfiConverterUInt64.read(from: &buf), coinType: try FfiConverterOptionUInt64.read(from: &buf), change: try FfiConverterOptionUInt64.read(from: &buf), path: try FfiConverterOptionString.read(from: &buf), ss58Prefix: try FfiConverterOptionUInt64.read(from: &buf), address: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .key(id: try FfiConverterString.read(from: &buf), name: try FfiConverterString.read(from: &buf), kind: try FfiConverterUInt64.read(from: &buf), keyData: try FfiConverterString.read(from: &buf), credentialId: try FfiConverterOptionString.read(from: &buf), handle: try FfiConverterOptionString.read(from: &buf), ua: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .watch(id: try FfiConverterString.read(from: &buf), name: try FfiConverterString.read(from: &buf), watch: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AccountRow, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .ua(id,name,kind,account,index,ua):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(id, into: &buf)
            FfiConverterString.write(name, into: &buf)
            FfiConverterUInt64.write(kind, into: &buf)
            FfiConverterUInt64.write(account, into: &buf)
            FfiConverterUInt64.write(index, into: &buf)
            FfiConverterString.write(ua, into: &buf)
            
        
        case let .native(id,name,network,index,coinType,change,path,ss58Prefix,address):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(id, into: &buf)
            FfiConverterString.write(name, into: &buf)
            FfiConverterString.write(network, into: &buf)
            FfiConverterUInt64.write(index, into: &buf)
            FfiConverterOptionUInt64.write(coinType, into: &buf)
            FfiConverterOptionUInt64.write(change, into: &buf)
            FfiConverterOptionString.write(path, into: &buf)
            FfiConverterOptionUInt64.write(ss58Prefix, into: &buf)
            FfiConverterString.write(address, into: &buf)
            
        
        case let .key(id,name,kind,keyData,credentialId,handle,ua):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(id, into: &buf)
            FfiConverterString.write(name, into: &buf)
            FfiConverterUInt64.write(kind, into: &buf)
            FfiConverterString.write(keyData, into: &buf)
            FfiConverterOptionString.write(credentialId, into: &buf)
            FfiConverterOptionString.write(handle, into: &buf)
            FfiConverterString.write(ua, into: &buf)
            
        
        case let .watch(id,name,watch):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(id, into: &buf)
            FfiConverterString.write(name, into: &buf)
            FfiConverterString.write(watch, into: &buf)
            
        }
    }
}


