    typealias SwiftType = DelaySentence

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> DelaySentence {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .atOnce
        
        case 2: return .after(delay: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 3: return .singleKey
        
        case 4: return .locked
        
        case 5: return .noDelay
        
        case 6: return .unknown
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: DelaySentence, into buf: inout [UInt8]) {
        switch value {
        
        
        case .atOnce:
            writeInt(&buf, Int32(1))
        
        
        case let .after(delay):
            writeInt(&buf, Int32(2))
            FfiConverterUInt64.write(delay, into: &buf)
            
        
        case .singleKey:
            writeInt(&buf, Int32(3))
        
        
        case .locked:
            writeInt(&buf, Int32(4))
        
        
        case .noDelay:
            writeInt(&buf, Int32(5))
        
        
        case .unknown:
            writeInt(&buf, Int32(6))
        
        }
    }
}


