/**
 * An SDK event (appended only).
 */

public enum Event: Equatable, Hashable {
    
    case seedUnlocked(seed: String
    )
    case seedLocked(seed: String
    )
    case keystoreChanged(rev: UInt64
    )
    case keystoreMismatch(seed: String
    )
    case keystoreRollback
    case hiddenOpsAbandoned(count: UInt32
    )
    /**
     * The subscriber's queue overflowed: `missed` events were dropped for it
     */
    case lagged(missed: UInt64
    )
    /**
     * An operation's state changed (spec §13.4, §13.5): every send result after `submit` arrives here, never as its error.
     */
    case opState(op: String, state: OpState
    )
    /**
     * A watched token's balance moved at the profile's final block (spec §14).
     */
    case balanceChanged(account: String, chain: String, token: String
    )
    /**
     * A watched account's new history items (spec §8.4), newest first.
     */
    case historyAdded(account: String, chain: String, items: [HistoryItem]
    )
    /**
     * Another process changed `sdk.state` (R17): its `rev` now.
     */
    case stateChanged(rev: UInt64
    )





}

#if compiler(>=6)
extension Event: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeEvent: FfiConverterRustBuffer {
    typealias SwiftType = Event

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Event {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .seedUnlocked(seed: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .seedLocked(seed: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .keystoreChanged(rev: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 4: return .keystoreMismatch(seed: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .keystoreRollback
        
        case 6: return .hiddenOpsAbandoned(count: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 7: return .lagged(missed: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 8: return .opState(op: try FfiConverterString.read(from: &buf), state: try FfiConverterTypeOpState.read(from: &buf)
        )
        
        case 9: return .balanceChanged(account: try FfiConverterString.read(from: &buf), chain: try FfiConverterString.read(from: &buf), token: try FfiConverterString.read(from: &buf)
        )
        
        case 10: return .historyAdded(account: try FfiConverterString.read(from: &buf), chain: try FfiConverterString.read(from: &buf), items: try FfiConverterSequenceTypeHistoryItem.read(from: &buf)
        )
        
        case 11: return .stateChanged(rev: try FfiConverterUInt64.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: Event, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .seedUnlocked(seed):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(seed, into: &buf)
            
        
        case let .seedLocked(seed):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(seed, into: &buf)
            
        
        case let .keystoreChanged(rev):
            writeInt(&buf, Int32(3))
            FfiConverterUInt64.write(rev, into: &buf)
            
        
        case let .keystoreMismatch(seed):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(seed, into: &buf)
            
        
        case .keystoreRollback:
            writeInt(&buf, Int32(5))
        
        
        case let .hiddenOpsAbandoned(count):
            writeInt(&buf, Int32(6))
            FfiConverterUInt32.write(count, into: &buf)
            
        
        case let .lagged(missed):
            writeInt(&buf, Int32(7))
            FfiConverterUInt64.write(missed, into: &buf)
            
        
        case let .opState(op,state):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(op, into: &buf)
            FfiConverterTypeOpState.write(state, into: &buf)
            
        
        case let .balanceChanged(account,chain,token):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(account, into: &buf)
            FfiConverterString.write(chain, into: &buf)
            FfiConverterString.write(token, into: &buf)
            
        
        case let .historyAdded(account,chain,items):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(account, into: &buf)
            FfiConverterString.write(chain, into: &buf)
            FfiConverterSequenceTypeHistoryItem.write(items, into: &buf)
            
        
        case let .stateChanged(rev):
            writeInt(&buf, Int32(11))
            FfiConverterUInt64.write(rev, into: &buf)
            
        }
    }
}


