        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .signed
        
        case 2: return .queued
        
        case 3: return .givenUpByEveryNode
        
        case 4: return .sent
        
        case 5: return .broadcastRejected
        
        case 6: return .txIncluded
        
        case 7: return .txFinalFailed
        
        case 8: return .txReplaced
        
        case 9: return .simRefused
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: InFlight, into buf: inout [UInt8]) {
        switch value {
        
        
        case .signed:
            writeInt(&buf, Int32(1))
        
        
        case .queued:
            writeInt(&buf, Int32(2))
        
        
        case .givenUpByEveryNode:
            writeInt(&buf, Int32(3))
        
        
        case .sent:
            writeInt(&buf, Int32(4))
        
        
        case .broadcastRejected:
            writeInt(&buf, Int32(5))
        
        
        case .txIncluded:
            writeInt(&buf, Int32(6))
        
        
        case .txFinalFailed:
            writeInt(&buf, Int32(7))
        
        
        case .txReplaced:
            writeInt(&buf, Int32(8))
        
        
        case .simRefused:
            writeInt(&buf, Int32(9))
        
        }
    }
}


