// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * An operation's state (spec §13.5, CLI-SDK-18): terminal only on a chain fact from a decisive read at the profile's final
 * block.
 */

public enum OpState: Equatable, Hashable {
    
    /**
     * the executed event of the operation's digest at or below the final block
     */
    case landed(block: UInt64, hash: String
    )
    /**
     * the lane's nonce spent at the final block without that event; a replaced native send
     */
    case consumed
    /**
     * an EVM native send final at or below the final block and reverted (owner 2026-11-18, ruling 4; the node's `reverted`)
     */
    case reverted(block: UInt64, hash: String
    )
    /**
     * `validUntil` below the final block's timestamp while the nonce is unspent
     */
    case expired
    /**
     * anything else, with what is known (never an end)
     */
    case inFlight(detail: InFlight
    )





}

#if compiler(>=6)
extension OpState: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeOpState: FfiConverterRustBuffer {
    typealias SwiftType = OpState

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> OpState {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .landed(block: try FfiConverterUInt64.read(from: &buf), hash: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .consumed
        
        case 3: return .reverted(block: try FfiConverterUInt64.read(from: &buf), hash: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .expired
        
        case 5: return .inFlight(detail: try FfiConverterTypeInFlight.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: OpState, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .landed(block,hash):
            writeInt(&buf, Int32(1))
            FfiConverterUInt64.write(block, into: &buf)
            FfiConverterString.write(hash, into: &buf)
            
        
        case .consumed:
            writeInt(&buf, Int32(2))
        
        
        case let .reverted(block,hash):
            writeInt(&buf, Int32(3))
            FfiConverterUInt64.write(block, into: &buf)
            FfiConverterString.write(hash, into: &buf)
            
        
        case .expired:
            writeInt(&buf, Int32(4))
        
        
        case let .inFlight(detail):
            writeInt(&buf, Int32(5))
            FfiConverterTypeInFlight.write(detail, into: &buf)
            
        }
    }
}


