// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * The `PayMeta` body by schema (pay-meta-tax spec §7.1), named.
 */

public enum PayBody: Equatable, Hashable {
    
    case none
    case note(note: String
    )
    case creditorRef(creditorRef: String, dueDate: UInt64
    )
    case boundCall(chainId: String, target: String, callHash: String
    )
    case ciphertext(ciphertext: String
    )





}

#if compiler(>=6)
extension PayBody: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypePayBody: FfiConverterRustBuffer {
    typealias SwiftType = PayBody

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> PayBody {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .none
        
        case 2: return .note(note: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .creditorRef(creditorRef: try FfiConverterString.read(from: &buf), dueDate: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 4: return .boundCall(chainId: try FfiConverterString.read(from: &buf), target: try FfiConverterString.read(from: &buf), callHash: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .ciphertext(ciphertext: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: PayBody, into buf: inout [UInt8]) {
        switch value {
        
        
        case .none:
            writeInt(&buf, Int32(1))
        
        
        case let .note(note):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(note, into: &buf)
            
        
        case let .creditorRef(creditorRef,dueDate):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(creditorRef, into: &buf)
            FfiConverterUInt64.write(dueDate, into: &buf)
            
        
        case let .boundCall(chainId,target,callHash):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(chainId, into: &buf)
            FfiConverterString.write(target, into: &buf)
            FfiConverterString.write(callHash, into: &buf)
            
        
        case let .ciphertext(ciphertext):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(ciphertext, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypePayBody_lift(_ buf: RustBuffer) throws -> PayBody {
    return try FfiConverterTypePayBody.lift(buf)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypePayBody_lower(_ value: PayBody) -> RustBuffer {
    return FfiConverterTypePayBody.lower(value)
}


