/**
 * A rescue vault's admin operation (CTR-GOV-25): `seq` the vault's shared order, from 1.
 */

public enum RescueOp: Equatable, Hashable {
    
    /**
     * `setRescuer(seq, newRescuer)`, `new_rescuer` an address (not 0)
     */
    case setRescuer(seq: UInt64, newRescuer: String
    )
    /**
     * `rotateAdmin(seq, newAdmin)`, `new_admin` a native UA (not 0)
     */
    case rotateAdmin(seq: UInt64, newAdmin: String
    )





}

#if compiler(>=6)
extension RescueOp: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeRescueOp: FfiConverterRustBuffer {
    typealias SwiftType = RescueOp

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> RescueOp {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .setRescuer(seq: try FfiConverterUInt64.read(from: &buf), newRescuer: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .rotateAdmin(seq: try FfiConverterUInt64.read(from: &buf), newAdmin: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: RescueOp, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .setRescuer(seq,newRescuer):
            writeInt(&buf, Int32(1))
            FfiConverterUInt64.write(seq, into: &buf)
            FfiConverterString.write(newRescuer, into: &buf)
            
        
        case let .rotateAdmin(seq,newAdmin):
            writeInt(&buf, Int32(2))
            FfiConverterUInt64.write(seq, into: &buf)
            FfiConverterString.write(newAdmin, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeRescueOp_lift(_ buf: RustBuffer) throws -> RescueOp {
    return try FfiConverterTypeRescueOp.lift(buf)
}

