@_documentation(visibility: private)
#endif
public struct FfiConverterTypeSlotKey: FfiConverterRustBuffer {
    typealias SwiftType = SlotKey

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SlotKey {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .ua(seed: try FfiConverterString.read(from: &buf), kind: try FfiConverterUInt16.read(from: &buf), account: try FfiConverterUInt32.read(from: &buf), index: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 2: return .native(seed: try FfiConverterString.read(from: &buf), network: try FfiConverterString.read(from: &buf), index: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 3: return .imported(seed: try FfiConverterString.read(from: &buf), network: try FfiConverterString.read(from: &buf), index: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 4: return .key(seed: try FfiConverterString.read(from: &buf), id: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .msig(ua: try FfiConverterString.read(from: &buf)
        )
        
        case 6: return .blsMulti(seed: try FfiConverterString.read(from: &buf), account: try FfiConverterUInt32.read(from: &buf), index: try FfiConverterUInt32.read(from: &buf), keyData: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .signed(signer: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: SlotKey, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .ua(seed,kind,account,index):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(seed, into: &buf)
            FfiConverterUInt16.write(kind, into: &buf)
            FfiConverterUInt32.write(account, into: &buf)
            FfiConverterUInt32.write(index, into: &buf)
            
        
        case let .native(seed,network,index):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(seed, into: &buf)
            FfiConverterString.write(network, into: &buf)
            FfiConverterUInt32.write(index, into: &buf)
            
        
        case let .imported(seed,network,index):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(seed, into: &buf)
            FfiConverterString.write(network, into: &buf)
            FfiConverterUInt32.write(index, into: &buf)
            
        
        case let .key(seed,id):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(seed, into: &buf)
            FfiConverterString.write(id, into: &buf)
            
        
        case let .msig(ua):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(ua, into: &buf)
            
        
        case let .blsMulti(seed,account,index,keyData):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(seed, into: &buf)
            FfiConverterUInt32.write(account, into: &buf)
            FfiConverterUInt32.write(index, into: &buf)
            FfiConverterString.write(keyData, into: &buf)
            
        
        case let .signed(signer):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(signer, into: &buf)
            
        }
    }
}


