        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .transfer(token: try FfiConverterString.read(from: &buf), to: try FfiConverterString.read(from: &buf), amount: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .initiateRecovery(account: try FfiConverterString.read(from: &buf), key: try FfiConverterTypeSubjectKeyArgs.read(from: &buf)
        )
        
        case 3: return .opaque(target: try FfiConverterString.read(from: &buf), value: try FfiConverterString.read(from: &buf), data: try FfiConverterString.read(from: &buf), allow: try FfiConverterOptionTypeAllowOpaqueCall.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: SmartCall, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .transfer(token,to,amount):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(token, into: &buf)
            FfiConverterString.write(to, into: &buf)
            FfiConverterString.write(amount, into: &buf)
            
        
        case let .initiateRecovery(account,key):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(account, into: &buf)
            FfiConverterTypeSubjectKeyArgs.write(key, into: &buf)
            
        
        case let .opaque(target,value,data,allow):
            writeInt(&buf, Int32(3))
